test:
store = ObjectStorageNamespace()
store.create_namespace('n', 'owner')
for call in (lambda: store.create_namespace('n', 'other'), lambda: store.create_namespace('', 'owner'), lambda: store.put('n', '', 'x', 'owner'), lambda: store.put('n', 'x', 3, 'owner'), lambda: store.list_objects('n', 'owner', None)):
    try:
        call()
        raise AssertionError('expected ValueError')
    except ValueError:
        pass
try:
    store.get('n', 'missing', 'owner')
    raise AssertionError('expected KeyError')
except KeyError:
    pass
assert store.list_objects('n', 'owner') == []
